        else: f = open(path, 'r', encoding='utf-8-sig', newline='')
    else: f = sys.stdin
    rows = list(csv.reader(f, delimiter=delim))
    if f is not sys.stdin: f.close()
    if no_headers: return None, rows
    return (rows[0] if rows else []), (rows[1:] if rows else [])

