"""Concatenate CSV inputs by row or column."""
import csv
import sys


def _read(path, delim):
    if delim is None:
        base = path.lower()
        if base.endswith('.gz'): base = base[:-3]
        ext = base.rsplit('.', 1)[-1] if '.' in base else ''
        delim = {'tsv': '\t', 'tab': '\t', 'psv': '|', 'ssv': ';', 'scsv': ';', 'cdx': ' '}.get(ext, ',')
    if path != '-' and path.lower().endswith('.gz'):
        import gzip
        f = gzip.open(path, 'rt', encoding='utf-8-sig', newline='')
    else:
        f = open(path, 'r', encoding='utf-8-sig', newline='') if path != '-' else sys.stdin
    try: return list(csv.reader(f, delimiter=delim))
    finally:
        if f is not sys.stdin: f.close()


def run(argv):
    mode = None; delim = None; out = '-'; no = False; pad = False
    paths_file = None; path_column = None; source_column = None; paths = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ('-h', '--help'):
            print('Concatenates CSV data by column or by row.\n\nUsage: xan cat rows|cols [options] [<inputs>...]')
            return 0
        if a in ('rows', 'cols', 'columns') and mode is None: mode = 'cols' if a != 'rows' else a
        elif a in ('-n', '--no-headers'): no = True
        elif a == '-p' or a == '--pad': pad = True
        elif a in ('-d', '--delimiter', '-o', '--output', '--paths', '--path-column', '-S', '--source-column'):
